values ('when-to-change-motorcycle-oil', 'when-to-change-motorcycle-oil', 'guides', 'guides-maintenance', 'published', '{"ru":"Когда менять масло в мотоцикле"}'::jsonb, '{"ru":"Когда менять масло"}'::jsonb, '{"ru":"Быстрый ориентир по срокам замены масла без поиска длинного регламента."}'::jsonb, '/assets/bot/oil.jpg', '{"lead":{"ru":"Масло меняют по регламенту конкретного мотоцикла, а не по универсальному совету."},"keyPoints":[{"ru":"Масло меняют по регламенту конкретного мотоцикла, а не по универсальному совету."},{"ru":"Важно учитывать пробег, время с последней замены и условия езды."},{"ru":"Фильтр обычно меняют вместе с маслом."}],"sections":[{"title":{"ru":"Практический ориентир"},"paragraphs":[{"ru":"Найди руководство владельца или сервисный регламент по своей модели. Если история обслуживания неизвестна, лучше заменить масло и фильтр в ближайшее время."}]},{"title":{"ru":"Когда проверить"},"paragraphs":[{"ru":"Перед сезоном, после покупки б/у мотоцикла, при достижении регламентного пробега или если масло давно не менялось по времени."}]},{"title":{"ru":"Почему это важно"},"paragraphs":[{"ru":"Старое или неподходящее масло хуже защищает двигатель и коробку, особенно в жару, пробках и активной езде."}]},{"title":{"ru":"Совет MG67"},"paragraphs":[{"ru":"Не выбирай масло только по совету из чата. Сначала спецификация, потом бренд."}]}],"disclaimer":{"ru":"Если не уверен в типе масла, фильтре или моменте затяжки, обратись в сервис."},"reviewedAt":"2026-07-24","ctas":[{"label":{"ru":"Мотомагазины"},"to":"/sections/places/moto-shops"},{"label":{"ru":"Мотосервисы"},"to":"/sections/places/services"},{"label":{"ru":"Проверка после зимы"},"to":"/guides/motorcycle-check-after-winter"}]}'::jsonb, '[{"ru":"масло"},{"ru":"замена масла"},{"ru":"регламент ТО"},{"ru":"масляный фильтр"}]'::jsonb, '{}', 'when-to-change-motorcycle-oil')
