values ('motorcycle-chain-care', 'motorcycle-chain-care', 'guides', 'guides-maintenance', 'published', '{"ru":"Как ухаживать за цепью"}'::jsonb, '{"ru":"Уход за цепью"}'::jsonb, '{"ru":"Что проверять новичку, чтобы цепь работала спокойно и безопасно."}'::jsonb, '/assets/bot/chain.jpg', '{"lead":{"ru":"Цепь нужно регулярно осматривать, очищать, смазывать и проверять на провис."},"keyPoints":[{"ru":"Цепь нужно регулярно осматривать, очищать, смазывать и проверять на провис."},{"ru":"Нельзя перетягивать цепь: это может навредить мотоциклу."},{"ru":"Звёзды оценивают вместе с цепью, а не отдельно."}],"sections":[{"title":{"ru":"Практический ориентир"},"paragraphs":[{"ru":"После дождя, грязи или длительной поездки осмотри цепь. Используй средства, подходящие для твоего типа цепи, и сверяй провис с руководством владельца."}]},{"title":{"ru":"Когда проверить"},"paragraphs":[{"ru":"Перед дальними поездками, после мойки, после дождя, после грязных дорог и при появлении рывков или шума."}]},{"title":{"ru":"Почему это важно"},"paragraphs":[{"ru":"Сухая, грязная или неправильно натянутая цепь ухудшает плавность хода и может привести к дорогому ремонту."}]},{"title":{"ru":"Совет MG67"},"paragraphs":[{"ru":"Лучше десять минут спокойного осмотра, чем одна поездка с перетянутой или сухой цепью."}]}],"disclaimer":{"ru":"Не чисти цепь на заведённом мотоцикле с включенной передачей. Это опасно."},"reviewedAt":"2026-07-24","ctas":[{"label":{"ru":"Мотомагазины"},"to":"/sections/places/moto-shops"},{"label":{"ru":"Мотосервисы"},"to":"/sections/places/services"}]}'::jsonb, '[{"ru":"цепь"},{"ru":"смазать цепь"},{"ru":"провис цепи"},{"ru":"звёзды"}]'::jsonb, '{}', 'motorcycle-chain-care')
