values ('motorcycle-tire-pressure', 'motorcycle-tire-pressure', 'guides', 'guides-maintenance', 'published', '{"ru":"Как проверять давление в шинах"}'::jsonb, '{"ru":"Давление в шинах"}'::jsonb, '{"ru":"Простой ритуал перед выездом, который сильно влияет на управление."}'::jsonb, '/assets/bot/tires.jpg', '{"lead":{"ru":"Давление проверяют на холодных шинах, до активной поездки."},"keyPoints":[{"ru":"Давление проверяют на холодных шинах, до активной поездки."},{"ru":"Ориентир берут из руководства или наклейки на мотоцикле."},{"ru":"Разные нагрузки могут требовать разного давления."}],"sections":[{"title":{"ru":"Практический ориентир"},"paragraphs":[{"ru":"Купи нормальный манометр и проверяй давление дома или до прогрева шин. Не ориентируйся только на ощущения."}]},{"title":{"ru":"Когда проверить"},"paragraphs":[{"ru":"Перед поездкой, после долгого простоя, при смене температуры и перед дальним маршрутом."}]},{"title":{"ru":"Почему это важно"},"paragraphs":[{"ru":"Неправильное давление меняет поведение мотоцикла, увеличивает износ резины и может ухудшить торможение."}]},{"title":{"ru":"Совет MG67"},"paragraphs":[{"ru":"Проверяй давление до выезда, а не на заправке после нескольких километров езды."}]}],"disclaimer":{"ru":"Если колесо быстро теряет давление, не продолжай ездить — ищи прокол или обратись в шиномонтаж."},"reviewedAt":"2026-07-24","ctas":[{"label":{"ru":"Мотошиномонтажи"},"to":"/sections/places/tire-services"},{"label":{"ru":"Проверка после зимы"},"to":"/guides/motorcycle-check-after-winter"}]}'::jsonb, '[{"ru":"давление"},{"ru":"шины"},{"ru":"резина"},{"ru":"манометр"},{"ru":"мотошиномонтаж"}]'::jsonb, '{}', 'motorcycle-tire-pressure')
