values ('motorcycle-check-after-winter', 'motorcycle-check-after-winter', 'guides', 'guides-maintenance', 'published', '{"ru":"Что проверить после зимнего хранения"}'::jsonb, '{"ru":"После зимы"}'::jsonb, '{"ru":"Короткий чек перед первым выездом после паузы."}'::jsonb, '/assets/bot/battery.jpg', '{"lead":{"ru":"После зимы не стоит сразу ехать далеко."},"keyPoints":[{"ru":"После зимы не стоит сразу ехать далеко."},{"ru":"Нужно проверить шины, аккумулятор, тормоза, свет, цепь и жидкости."},{"ru":"Первый выезд лучше сделать коротким и спокойным."}],"sections":[{"title":{"ru":"Практический ориентир"},"paragraphs":[{"ru":"Поставь мотоцикл на ровное место, проверь базовые узлы и только потом планируй короткий круг без спешки."}]},{"title":{"ru":"Когда проверить"},"paragraphs":[{"ru":"Перед первым весенним выездом и после любого долгого простоя."}]},{"title":{"ru":"Почему это важно"},"paragraphs":[{"ru":"За зиму могли измениться давление в шинах, заряд аккумулятора, состояние цепи и тормозов."}]},{"title":{"ru":"Совет MG67"},"paragraphs":[{"ru":"Первый день сезона — не день рекордов. Сначала техника и ощущения, потом маршруты."}]}],"disclaimer":{"ru":"Если тормоза, резина или электрика вызывают сомнения, лучше не выезжать до проверки."},"reviewedAt":"2026-07-24","ctas":[{"label":{"ru":"Давление в шинах"},"to":"/guides/motorcycle-tire-pressure"},{"label":{"ru":"Уход за цепью"},"to":"/guides/motorcycle-chain-care"}]}'::jsonb, '[{"ru":"после зимы"},{"ru":"начало сезона"},{"ru":"аккумулятор"},{"ru":"первый выезд"}]'::jsonb, '{}', 'motorcycle-check-after-winter')
