values ('helmet-first', 'choose-first-helmet', 'guides', 'guides-gear', 'published', '{"ru":"Как выбрать первый мотошлем"}'::jsonb, '{"ru":"Первый шлем"}'::jsonb, '{"ru":"Первый шлем выбирают по посадке, сертификации и формату, а не только по внешнему виду."}'::jsonb, '/assets/bot/helmet.jpg', '{"lead":{"ru":"Для новичка самый универсальный вариант — интеграл."},"keyPoints":[{"ru":"Для новичка самый универсальный вариант — интеграл."},{"ru":"Шлем должен сидеть плотно, но не давить больно."},{"ru":"Сертификация ECE 22.06 или ECE 22.05 важнее красивой графики."}],"sections":[{"title":{"ru":"Практический ориентир"},"paragraphs":[{"ru":"Померь несколько моделей и походи в каждой 10-15 минут. Проверь лоб, виски, обзор, визор и ощущение при повороте головы."}]},{"title":{"ru":"Когда проверить"},"paragraphs":[{"ru":"До покупки первого мотоцикла или до первых самостоятельных выездов."}]},{"title":{"ru":"Почему это важно"},"paragraphs":[{"ru":"Неудобный или слишком большой шлем отвлекает, хуже защищает и быстро начинает раздражать."}]},{"title":{"ru":"Совет MG67"},"paragraphs":[{"ru":"Первый шлем — это не про самый красивый комплект. Сначала безопасность и комфорт, потом стиль."}]}],"disclaimer":{"ru":"Не покупай б/у шлем без понимания его истории. После сильного удара шлем лучше заменить."},"reviewedAt":"2026-07-24","ctas":[{"label":{"ru":"Первые перчатки"},"to":"/guides/gloves-first"},{"label":{"ru":"Что купить сначала"},"to":"/guides/gear-first-priority"},{"label":{"ru":"Мотомагазины"},"to":"/sections/places/moto-shops"}]}'::jsonb, '[{"ru":"шлем"},{"ru":"первый шлем"},{"ru":"интеграл"},{"ru":"экипировка"}]'::jsonb, '{}', 'helmet-first')
