values ('gloves-first', 'gloves-first', 'guides', 'guides-gear', 'published', '{"ru":"Как выбрать первые мотоперчатки"}'::jsonb, '{"ru":"Первые перчатки"}'::jsonb, '{"ru":"Перчатки должны защищать ладони и не мешать управлению."}'::jsonb, '/assets/bot/gloves.jpg', '{"lead":{"ru":"Перчатки нужны даже для коротких поездок."},"keyPoints":[{"ru":"Перчатки нужны даже для коротких поездок."},{"ru":"Размер должен позволять нормально чувствовать рычаги и кнопки."},{"ru":"Защита ладони и костяшек важнее декоративного вида."}],"sections":[{"title":{"ru":"Практический ориентир"},"paragraphs":[{"ru":"Надень перчатки и попробуй имитировать работу газом, сцеплением, тормозом и кнопками. Швы не должны давить."}]},{"title":{"ru":"Когда проверить"},"paragraphs":[{"ru":"Сразу после шлема, до первых городских выездов."}]},{"title":{"ru":"Почему это важно"},"paragraphs":[{"ru":"При падении человек часто инстинктивно выставляет руки. Ладони страдают первыми."}]},{"title":{"ru":"Совет MG67"},"paragraphs":[{"ru":"Не бери слишком толстые перчатки “на всякий случай”, если в них теряется чувство рычагов."}]}],"disclaimer":{"ru":"Обычные строительные или зимние перчатки не заменяют мотоперчатки."},"reviewedAt":"2026-07-24","ctas":[{"label":{"ru":"Первый шлем"},"to":"/guides/choose-first-helmet"},{"label":{"ru":"Что купить сначала"},"to":"/guides/gear-first-priority"}]}'::jsonb, '[{"ru":"перчатки"},{"ru":"мотоперчатки"},{"ru":"экипировка"},{"ru":"защита рук"}]'::jsonb, '{}', 'gloves-first')
