values ('documents-after-category-a', 'documents-after-category-a', 'guides', 'guides-documents', 'published', '{"ru":"Что сделать после получения категории А"}'::jsonb, '{"ru":"После категории А"}'::jsonb, '{"ru":"Первые шаги после прав: документы, практика и спокойный старт."}'::jsonb, '/assets/bot/theory_a.jpg', '{"lead":{"ru":"Права — это допуск к дороге, а не конец обучения."},"keyPoints":[{"ru":"Права — это допуск к дороге, а не конец обучения."},{"ru":"Сначала проверь документы, страховку, экипировку и базовые навыки."},{"ru":"Первые поездки лучше делать короткими и понятными."}],"sections":[{"title":{"ru":"Практический ориентир"},"paragraphs":[{"ru":"Собери документы, оформи ОСАГО, проверь экипировку и запланируй несколько спокойных тренировок перед активным городом."}]},{"title":{"ru":"Когда проверить"},"paragraphs":[{"ru":"Сразу после получения категории А и перед первой самостоятельной поездкой."}]},{"title":{"ru":"Почему это важно"},"paragraphs":[{"ru":"Новичку важно не перегрузить себя в первые дни и не попасть в город без базовой готовности."}]},{"title":{"ru":"Совет MG67"},"paragraphs":[{"ru":"После экзамена не надо сразу доказывать себе, что ты всё умеешь. Лучше спокойно собрать основу."}]}],"disclaimer":{"ru":"Не выезжай без документов, ОСАГО и исправного мотоцикла."},"reviewedAt":"2026-07-24","ctas":[{"label":{"ru":"ОСАГО для новичка"},"to":"/guides/osago-beginner"},{"label":{"ru":"Спокойный старт сезона"},"to":"/guides/first-season-start"}]}'::jsonb, '[{"ru":"категория а"},{"ru":"получил права"},{"ru":"что делать после экзамена"},{"ru":"документы"}]'::jsonb, '{}', 'documents-after-category-a')
