values ('first-season-start', 'first-season-start', 'guides', 'guides-season', 'published', '{"ru":"Как спокойно начать первый мотосезон"}'::jsonb, '{"ru":"Спокойный старт"}'::jsonb, '{"ru":"Первый сезон лучше начинать не с героизма, а с понятного плана."}'::jsonb, '/assets/bot/first_ride.jpg', '{"lead":{"ru":"Начинай с коротких поездок и знакомых маршрутов."},"keyPoints":[{"ru":"Начинай с коротких поездок и знакомых маршрутов."},{"ru":"Не совмещай сразу новый мотоцикл, новый город и сложные задачи."},{"ru":"Регулярные маленькие выезды полезнее редких больших подвигов."}],"sections":[{"title":{"ru":"Практический ориентир"},"paragraphs":[{"ru":"Выбери спокойное время, короткий маршрут, проверь мотоцикл и заранее реши, где остановишься, если устанешь."}]},{"title":{"ru":"Когда проверить"},"paragraphs":[{"ru":"В первые недели после покупки мотоцикла или после долгого перерыва."}]},{"title":{"ru":"Почему это важно"},"paragraphs":[{"ru":"Перегрузка в начале сезона быстро забирает внимание и уверенность."}]},{"title":{"ru":"Совет MG67"},"paragraphs":[{"ru":"Хороший первый сезон строится не на скорости, а на повторяемости и спокойствии."}]}],"disclaimer":{"ru":"Не выезжай в сложный поток, если устал, нервничаешь или плохо чувствуешь мотоцикл."},"reviewedAt":"2026-07-24","ctas":[{"label":{"ru":"После категории А"},"to":"/guides/documents-after-category-a"},{"label":{"ru":"Не бояться города"},"to":"/guides/city-fear"}]}'::jsonb, '[{"ru":"первый сезон"},{"ru":"первый выезд"},{"ru":"новичок"},{"ru":"спокойный старт"}]'::jsonb, '{}', 'first-season-start')
