values ('visibility-city', 'visibility-city', 'guides', 'guides-safety', 'published', '{"ru":"Как быть заметнее в городе"}'::jsonb, '{"ru":"Быть заметнее"}'::jsonb, '{"ru":"Простые решения, которые помогают водителям раньше увидеть мотоциклиста."}'::jsonb, '/assets/bot/city_lane_position.jpg', '{"lead":{"ru":"Заметность — это свет, позиция, контраст и предсказуемость."},"keyPoints":[{"ru":"Заметность — это свет, позиция, контраст и предсказуемость."},{"ru":"Не рассчитывай, что водитель обязательно тебя увидел."},{"ru":"Слепые зоны и перекрёстки требуют особого внимания."}],"sections":[{"title":{"ru":"Практический ориентир"},"paragraphs":[{"ru":"Используй свет, выбирай видимую позицию в полосе, избегай долгого движения рядом с бортом автомобиля и не прячься в тёмной одежде ночью."}]},{"title":{"ru":"Когда проверить"},"paragraphs":[{"ru":"Каждый раз в городе, особенно вечером, в дождь и в плотном потоке."}]},{"title":{"ru":"Почему это важно"},"paragraphs":[{"ru":"Мотоцикл маленький и быстро пропадает из внимания водителей."}]},{"title":{"ru":"Совет MG67"},"paragraphs":[{"ru":"Твоя задача не доказать право на полосу, а сделать себя понятным и заметным."}]}],"disclaimer":{"ru":"Яркая экипировка не отменяет дистанцию, скорость и работу взглядом."},"reviewedAt":"2026-07-24","ctas":[{"label":{"ru":"Слепые зоны"},"to":"/guides/blind-zones"},{"label":{"ru":"Не бояться города"},"to":"/guides/city-fear"}]}'::jsonb, '[{"ru":"город"},{"ru":"заметность"},{"ru":"отражайки"},{"ru":"свет"},{"ru":"безопасность"}]'::jsonb, '{}', 'visibility-city')
