values ('city-fear', 'city-fear', 'guides', 'guides-safety', 'published', '{"ru":"Как перестать бояться города на мотоцикле"}'::jsonb, '{"ru":"Не бояться города"}'::jsonb, '{"ru":"Как снижать нагрузку и входить в поток постепенно."}'::jsonb, '/assets/bot/city_blindspot.jpg', '{"lead":{"ru":"Страх города часто связан не со слабостью, а с перегрузкой внимания."},"keyPoints":[{"ru":"Страх города часто связан не со слабостью, а с перегрузкой внимания."},{"ru":"Начинай с простых маршрутов и спокойного времени."},{"ru":"Навык приходит через повторение, а не через резкий “рывок”."}],"sections":[{"title":{"ru":"Практический ориентир"},"paragraphs":[{"ru":"Выбери знакомый короткий маршрут, проедь его в тихое время, затем постепенно добавляй новые участки и задачи."}]},{"title":{"ru":"Когда проверить"},"paragraphs":[{"ru":"Если после получения прав город кажется слишком хаотичным или страшным."}]},{"title":{"ru":"Почему это важно"},"paragraphs":[{"ru":"Постепенность помогает мозгу привыкнуть к потоку, знакам, зеркалам, скорости и решениям."}]},{"title":{"ru":"Совет MG67"},"paragraphs":[{"ru":"Не ставь цель “не бояться вообще”. Ставь цель ехать чуть спокойнее, чем вчера."}]}],"disclaimer":{"ru":"Если паника мешает управлению, лучше потренироваться с инструктором на площадке и в городе."},"reviewedAt":"2026-07-24","ctas":[{"label":{"ru":"Тренировочные площадки"},"to":"/sections/places/training-areas"},{"label":{"ru":"Быть заметнее"},"to":"/guides/visibility-city"}]}'::jsonb, '[{"ru":"страх города"},{"ru":"город"},{"ru":"поток"},{"ru":"новичок"},{"ru":"уверенность"}]'::jsonb, '{}', 'city-fear')
