values ('blind-zones', 'blind-zones', 'guides', 'guides-safety', 'published', '{"ru":"Как не попадать в слепые зоны автомобилей"}'::jsonb, '{"ru":"Слепые зоны"}'::jsonb, '{"ru":"Городской принцип про видимость, дистанцию и позицию рядом с машинами."}'::jsonb, '/assets/bot/city_blindspot.jpg', '{"lead":{"ru":"Если ты не видишь лицо водителя или зеркало, есть риск, что тебя тоже не видят."},"keyPoints":[{"ru":"Если ты не видишь лицо водителя или зеркало, есть риск, что тебя тоже не видят."},{"ru":"Не зависай сбоку от автомобиля дольше необходимого."},{"ru":"Особенно осторожно рядом с грузовиками, автобусами и такси."}],"sections":[{"title":{"ru":"Практический ориентир"},"paragraphs":[{"ru":"Держи позицию, где тебя проще заметить. Либо проходи опасную зону спокойно и предсказуемо, либо оставайся позади с дистанцией."}]},{"title":{"ru":"Когда проверить"},"paragraphs":[{"ru":"В потоке, перед перестроениями, на перекрёстках и рядом с крупным транспортом."}]},{"title":{"ru":"Почему это важно"},"paragraphs":[{"ru":"Автомобиль может начать перестроение именно в тот момент, когда мотоцикл находится вне обзора."}]},{"title":{"ru":"Совет MG67"},"paragraphs":[{"ru":"Не борись за место в слепой зоне. Лучшее решение — не находиться там."}]}],"disclaimer":{"ru":"Не ускоряйся резко рядом с машиной, если водитель уже начал манёвр."},"reviewedAt":"2026-07-24","ctas":[{"label":{"ru":"Быть заметнее"},"to":"/guides/visibility-city"},{"label":{"ru":"Не бояться города"},"to":"/guides/city-fear"}]}'::jsonb, '[{"ru":"слепые зоны"},{"ru":"город"},{"ru":"перестроение"},{"ru":"дистанция"}]'::jsonb, '{}', 'blind-zones')
